import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { getSet, getCards, addCardToSet, removeCardFromSet } from '../services/api';

const SetDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [set, setSet] = useState(null);
  const [allCards, setAllCards] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedCardId, setSelectedCardId] = useState('');
  const [addingCard, setAddingCard] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [setData, cardsData] = await Promise.all([
          getSet(id),
          getCards()
        ]);
        setSet(setData);
        setAllCards(cardsData);
        setLoading(false);
      } catch (err) {
        setError('Failed to fetch data. Please try again later.');
        setLoading(false);
      }
    };

    fetchData();
  }, [id]);

  const handleAddCard = async () => {
    if (!selectedCardId) {
      return;
    }

    setAddingCard(true);
    try {
      await addCardToSet(id, selectedCardId);
      
      // Refresh set data to show the new card
      const updatedSet = await getSet(id);
      setSet(updatedSet);
      setSelectedCardId('');
    } catch (err) {
      setError('Failed to add card to set. Please try again.');
    } finally {
      setAddingCard(false);
    }
  };

  const handleRemoveCard = async (cardId) => {
    if (window.confirm('Are you sure you want to remove this card from the set?')) {
      try {
        await removeCardFromSet(id, cardId);
        
        // Update the local state to remove the card
        setSet({
          ...set,
          cards: set.cards.filter(card => card._id !== cardId)
        });
      } catch (err) {
        setError('Failed to remove card from set. Please try again.');
      }
    }
  };

  // Filter out cards that are already in the set
  const availableCards = allCards.filter(card => 
    !set?.cards.some(setCard => setCard._id === card._id)
  );

  if (loading) {
    return <div className="loading">Loading set details...</div>;
  }

  if (error) {
    return <div className="error-message">{error}</div>;
  }

  if (!set) {
    return <div className="error-message">Set not found.</div>;
  }

  return (
    <div className="set-detail-page">
      <div className="header">
        <h1>{set.name}</h1>
        <div className="header-actions">
          <button 
            className="btn btn-edit"
            onClick={() => navigate(`/sets/edit/${id}`)}
          >
            Edit Set
          </button>
          <button 
            className="btn btn-secondary"
            onClick={() => navigate('/sets')}
          >
            Back to Sets
          </button>
        </div>
      </div>

      {set.description && (
        <div className="set-description-box">
          <p>{set.description}</p>
        </div>
      )}

      <div className="set-management">
        <h2>Add Cards to Set</h2>
        <div className="add-card-form">
          <select
            className="form-control"
            value={selectedCardId}
            onChange={(e) => setSelectedCardId(e.target.value)}
          >
            <option value="">Select a card to add</option>
            {availableCards.map(card => (
              <option key={card._id} value={card._id}>
                {card.title} ({card.rarity} {card.class})
              </option>
            ))}
          </select>
          <button 
            className="btn"
            onClick={handleAddCard}
            disabled={!selectedCardId || addingCard}
          >
            {addingCard ? 'Adding...' : 'Add to Set'}
          </button>
        </div>
      </div>

      <h2>Cards in this Set ({set.cards.length})</h2>
      
      {set.cards.length === 0 ? (
        <div className="no-cards">
          <p>No cards in this set yet. Add some cards from the dropdown above.</p>
        </div>
      ) : (
        <div className="set-cards">
          {set.cards.map(card => (
            <div className="set-card-item" key={card._id}>
              <div className="set-card-image">
                <img src={card.imageUrl} alt={card.title} />
              </div>
              <div className="set-card-info">
                <h3>{card.title}</h3>
                <div className="set-card-meta">
                  <span className="card-class">{card.class}</span>
                  <span className="card-rarity">{card.rarity}</span>
                </div>
                <div className="set-card-stats">
                  <div>
                    <span>Attack: <span className="attack-value">{card.unevolvedAttack}</span></span>
                    <span>Defense: <span className="defense-value">{card.unevolvedDefense}</span></span>
                  </div>
                </div>
                <div className="set-card-actions">
                  <Link to={`/edit/${card._id}`} className="btn btn-edit">Edit Card</Link>
                  <button 
                    className="btn btn-danger"
                    onClick={() => handleRemoveCard(card._id)}
                  >
                    Remove from Set
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default SetDetail;
